import type {
  IndexFilterItemType,
  IndexFilterSortOptionType,
  TabItemType,
} from "@xco-agency/corex-ui";
import type {
  ProductIndexColumnType,
  ProductIndexItemType,
  ProductIndexSortType,
  ProductIndexStatusTabIdType,
} from "./types";
import productsJson from "./products.json";

export const PRODUCT_INDEX_PAGE_SIZE = 50;

/** 100 mock products; replace with your own data source. */
export const MOCK_PRODUCTS = productsJson as ProductIndexItemType[];

export const PRODUCT_INDEX_STATUS_TABS: TabItemType<ProductIndexStatusTabIdType>[] = [
  { id: "all", label: "All" },
  { id: "active", label: "Active" },
  { id: "draft", label: "Draft" },
  { id: "archived", label: "Archived" },
];

const OPERATORS = [
  { label: "Is", value: "is" },
  { label: "Is not", value: "is_not" },
];

const optionsFrom = (values: string[]) =>
  [...new Set(values)].sort().map((value) => ({ label: value, value }));

export const PRODUCT_INDEX_FILTERS: IndexFilterItemType[] = [
  {
    key: "status",
    label: "Status",
    allowMultiple: false,
    operators: OPERATORS,
    options: [
      { label: "Active", value: "active" },
      { label: "Draft", value: "draft" },
      { label: "Archived", value: "archived" },
    ],
  },
  {
    key: "vendor",
    label: "Vendor",
    operators: OPERATORS,
    options: optionsFrom(MOCK_PRODUCTS.map((product) => product.vendor)),
  },
  {
    key: "category",
    label: "Category",
    operators: OPERATORS,
    options: optionsFrom(MOCK_PRODUCTS.map((product) => product.category)),
  },
  {
    key: "tag",
    label: "Tag",
    operators: OPERATORS,
    options: optionsFrom(MOCK_PRODUCTS.flatMap((product) => product.tags)),
  },
];

export const PRODUCT_INDEX_SORT_OPTIONS: IndexFilterSortOptionType[] = [
  { label: "Updated", value: "updatedAt" },
  { label: "Product title", value: "title" },
  { label: "Inventory", value: "inventory" },
  { label: "Price", value: "price" },
];

export const DEFAULT_PRODUCT_INDEX_SORT: ProductIndexSortType = {
  key: "updatedAt",
  direction: "descending",
};

export const PRODUCT_INDEX_COLUMNS: ProductIndexColumnType[] = [
  // The product column stays first and can't be hidden.
  {
    key: "product",
    label: "Product",
    reorderable: false,
    hideable: false,
    minWidth: 260,
    sticky: "left",
  },
  { key: "status", label: "Status", minWidth: 110 },
  { key: "inventory", label: "Inventory", minWidth: 170 },
  { key: "category", label: "Category", minWidth: 130 },
  { key: "vendor", label: "Vendor", minWidth: 140 },
  { key: "productType", label: "Type", minWidth: 120, visible: false },
  { key: "channels", label: "Channels", minWidth: 100, alignment: "center" },
  { key: "price", label: "Price", minWidth: 100, alignment: "end" },
  { key: "updatedAt", label: "Updated", minWidth: 120, visible: false },
];

import { useMemo, useState } from "react";
import { Banner, BlockStack, Page, useIndexResourceState } from "@xco-agency/corex-ui";
import type { IndexFiltersSavedViewType, TabItemType } from "@xco-agency/corex-ui";
import {
  DEFAULT_PRODUCT_INDEX_SORT,
  MOCK_PRODUCTS,
  PRODUCT_INDEX_COLUMNS,
  PRODUCT_INDEX_FILTERS,
  PRODUCT_INDEX_PAGE_SIZE,
  PRODUCT_INDEX_SORT_OPTIONS,
  PRODUCT_INDEX_STATUS_TABS,
} from "../constants";
import { ProductIndexEmptyState } from "../partials/ProductIndexEmptyState";
import { ProductIndexFilters } from "../partials/ProductIndexFilters";
import { ProductIndexTable } from "../partials/ProductIndexTable";
import { fromSavedFilters, matchesFilters, sortProducts } from "../utils";
import type {
  ProductIndexColumnType,
  ProductIndexFilterValueType,
  ProductIndexItemType,
  ProductIndexSavedViewType,
  ProductIndexSortType,
  ProductIndexStatusType,
} from "../types";

export function ProductIndexExample() {
  const [products, setProducts] = useState<ProductIndexItemType[]>(MOCK_PRODUCTS);
  const [selectedTab, setSelectedTab] = useState("all");
  const [savedViews, setSavedViews] = useState<ProductIndexSavedViewType[]>([]);
  const [query, setQuery] = useState("");
  const [appliedFilters, setAppliedFilters] = useState<ProductIndexFilterValueType[]>([]);
  const [sort, setSort] = useState<ProductIndexSortType>(DEFAULT_PRODUCT_INDEX_SORT);
  const [hideArchived, setHideArchived] = useState(false);
  const [columns, setColumns] = useState<ProductIndexColumnType[]>(PRODUCT_INDEX_COLUMNS);
  const [page, setPage] = useState(1);
  const [refreshing, setRefreshing] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);

  const showNotice = (message: string) => {
    setNotice(message);
    setTimeout(() => setNotice(null), 4000);
  };

  /* ---------------------------------------------------------------- views */

  const savedView = savedViews.find((view) => view.id === selectedTab);
  const statusTab = PRODUCT_INDEX_STATUS_TABS.find((tab) => tab.id === selectedTab);

  const tabs: TabItemType[] = [
    ...PRODUCT_INDEX_STATUS_TABS,
    ...savedViews.map((view) => ({ id: view.id, label: view.name })),
  ];

  const handleSelectTab = (tabId: string) => {
    setSelectedTab(tabId);
    setPage(1);
    // Each view owns its search and filters: saved views restore theirs,
    // status tabs start clean.
    const view = savedViews.find((item) => item.id === tabId);
    setQuery(view?.query ?? "");
    setAppliedFilters(view?.filters ?? []);
  };

  const handleSaveView = (view: IndexFiltersSavedViewType) => {
    const id = `view-${Date.now()}`;
    setSavedViews((prev) => [
      ...prev,
      { id, name: view.name, query: view.query, filters: fromSavedFilters(view.filters) },
    ]);
    setSelectedTab(id);
    showNotice(`View "${view.name}" saved.`);
  };

  const handleDeleteView = () => {
    if (!savedView) return;
    setSavedViews((prev) => prev.filter((view) => view.id !== savedView.id));
    handleSelectTab("all");
    showNotice(`View "${savedView.name}" deleted.`);
  };

  /* ------------------------------------------------------------- filtering */

  const filteredProducts = useMemo(() => {
    const status = statusTab && statusTab.id !== "all" ? statusTab.id : null;
    const visible = products.filter(
      (product) =>
        (!status || product.status === status) &&
        !(hideArchived && product.status === "archived") &&
        matchesFilters(product, query, appliedFilters),
    );
    return sortProducts(visible, sort);
  }, [products, statusTab, hideArchived, query, appliedFilters, sort]);

  const pageCount = Math.max(
    1,
    Math.ceil(filteredProducts.length / PRODUCT_INDEX_PAGE_SIZE),
  );
  const currentPage = Math.min(page, pageCount);
  const pageProducts = filteredProducts.slice(
    (currentPage - 1) * PRODUCT_INDEX_PAGE_SIZE,
    currentPage * PRODUCT_INDEX_PAGE_SIZE,
  );

  const handleQueryChange = (next: string) => {
    setQuery(next);
    setPage(1);
  };

  const handleFiltersChange = (next: ProductIndexFilterValueType[]) => {
    setAppliedFilters(next);
    setPage(1);
  };

  const handleClearAll = () => {
    setQuery("");
    setAppliedFilters([]);
    setPage(1);
  };

  /* ------------------------------------------------------------- selection */

  const {
    selectedResources,
    allResourcesSelected,
    handleSelectionChange,
    clearSelection,
  } = useIndexResourceState(filteredProducts);

  const handleBulkStatusChange = (status: ProductIndexStatusType) => {
    const ids = new Set(selectedResources);
    setProducts((prev) =>
      prev.map((product) => (ids.has(product.id) ? { ...product, status } : product)),
    );
    showNotice(`${ids.size} product(s) set to ${status}.`);
    clearSelection();
  };

  const handleBulkDelete = () => {
    const ids = new Set(selectedResources);
    setProducts((prev) => prev.filter((product) => !ids.has(product.id)));
    showNotice(`${ids.size} product(s) deleted.`);
    clearSelection();
  };

  /* --------------------------------------------------------------- actions */

  const handleRefresh = () => {
    setRefreshing(true);
    setTimeout(() => setRefreshing(false), 700);
  };

  const handleExport = () =>
    showNotice(`Exporting ${filteredProducts.length} filtered product(s) as CSV.`);

  return (
    <Page
      heading="Products"
      primaryAction={{
        content: "Add product",
        onAction: () => showNotice("Opening the new product form."),
      }}
    >
      <BlockStack gap="small-200">
        {notice ? (
          <Banner tone="info" onDismiss={() => setNotice(null)}>
            {notice}
          </Banner>
        ) : null}

        <ProductIndexFilters
          tabs={tabs}
          selectedTab={selectedTab}
          onSelectTab={handleSelectTab}
          query={query}
          onQueryChange={handleQueryChange}
          filterDefinitions={PRODUCT_INDEX_FILTERS}
          appliedFilters={appliedFilters}
          onAppliedFiltersChange={handleFiltersChange}
          onClearAll={handleClearAll}
          sortOptions={PRODUCT_INDEX_SORT_OPTIONS}
          sort={sort}
          onSortChange={setSort}
          hideArchived={hideArchived}
          onHideArchivedChange={setHideArchived}
          columns={columns}
          onColumnsChange={setColumns}
          existingViewNames={tabs.map((tab) => tab.label ?? "")}
          onSaveView={handleSaveView}
          onDeleteView={savedView ? handleDeleteView : undefined}
          onExport={handleExport}
          onRefresh={handleRefresh}
          refreshing={refreshing}
        />

        <ProductIndexTable
          products={pageProducts}
          totalCount={filteredProducts.length}
          columns={columns}
          selectedIds={selectedResources}
          allSelected={allResourcesSelected}
          onSelectionChange={handleSelectionChange}
          sort={sort}
          onSortChange={setSort}
          page={currentPage}
          pageCount={pageCount}
          pageSize={PRODUCT_INDEX_PAGE_SIZE}
          onPageChange={setPage}
          onBulkStatusChange={handleBulkStatusChange}
          onBulkDelete={handleBulkDelete}
          onOpenProduct={(product) => showNotice(`Opening "${product.title}".`)}
          emptyState={<ProductIndexEmptyState onClearAll={handleClearAll} />}
          loading={refreshing}
        />
      </BlockStack>
    </Page>
  );
}

export * from "./types";
export * from "./constants";
export * from "./utils";
export { ProductIndexFilters } from "./partials/ProductIndexFilters";
export { ProductIndexTable } from "./partials/ProductIndexTable";
export { ProductIndexEmptyState } from "./partials/ProductIndexEmptyState";
export { ProductIndexExample } from "./examples/ProductIndexExample";

import { Box, EmptyState, Link, Text } from "@xco-agency/corex-ui";
import type { ProductIndexEmptyStatePropsType } from "../types";

/** Shown inside the table when no product matches the search and filters. */
export function ProductIndexEmptyState({ onClearAll }: ProductIndexEmptyStatePropsType) {
  return (
    <Box paddingBlock="large-300" paddingInline="large-100">
      <EmptyState
        heading="No products found"
        icon="search"
        action={{ content: "Clear search and filters", onAction: onClearAll }}
        footerContent={<Link url="#">Learn more about products</Link>}
      >
        <Text color="subdued">Try changing the filters or search term.</Text>
      </EmptyState>
    </Box>
  );
}

import { Button, IndexFilters, Tabs } from "@xco-agency/corex-ui";
import type { IndexAppliedFilterType } from "@xco-agency/corex-ui";
import { toOperator } from "../utils";
import type {
  ProductIndexFilterKeyType,
  ProductIndexFilterValueType,
  ProductIndexFiltersPropsType,
  ProductIndexSortKeyType,
} from "../types";

/**
 * IndexFilters toolbar: view tabs, search with filter pills, view options
 * (sort, hide archived, columns) and actions. "Save" is built into
 * IndexFilters; Export expands next to it only while filters are active.
 */
export function ProductIndexFilters({
  tabs,
  selectedTab,
  onSelectTab,
  query,
  onQueryChange,
  filterDefinitions,
  appliedFilters,
  onAppliedFiltersChange,
  onClearAll,
  sortOptions,
  sort,
  onSortChange,
  hideArchived,
  onHideArchivedChange,
  columns,
  onColumnsChange,
  existingViewNames,
  onSaveView,
  onDeleteView,
  onExport,
  onRefresh,
  refreshing,
}: ProductIndexFiltersPropsType) {
  const removeFilter = (key: string) =>
    onAppliedFiltersChange(appliedFilters.filter((filter) => filter.key !== key));

  const pills: IndexAppliedFilterType[] = appliedFilters.map((filter) => ({
    key: filter.key,
    field: filterDefinitions.find((def) => def.key === filter.key)?.label,
    operator: filter.operator,
    value: filter.value,
    onRemove: removeFilter,
  }));

  const handleAddFilter = (key: string, index: number) => {
    if (appliedFilters.some((filter) => filter.key === key)) return;
    const def = filterDefinitions.find((item) => item.key === key);
    const next = [...appliedFilters];
    // Insert the pill where the caret was when the filter was picked.
    next.splice(index, 0, {
      key: key as ProductIndexFilterKeyType,
      operator: toOperator(def?.defaultOperator),
      value: def?.allowMultiple === false ? "" : [],
    });
    onAppliedFiltersChange(next);
  };

  const handleFilterSelect = (
    key: string,
    value: string | string[],
    operator?: string,
  ) => {
    const isEmpty = Array.isArray(value) ? value.length === 0 : !value;
    if (isEmpty) {
      removeFilter(key);
      return;
    }
    const updated: ProductIndexFilterValueType = {
      key: key as ProductIndexFilterKeyType,
      operator: toOperator(operator),
      value,
    };
    const exists = appliedFilters.some((filter) => filter.key === key);
    onAppliedFiltersChange(
      exists
        ? appliedFilters.map((filter) => (filter.key === key ? updated : filter))
        : [...appliedFilters, updated],
    );
  };

  const handleOperatorChange = (key: string, operator: string) =>
    onAppliedFiltersChange(
      appliedFilters.map((filter) =>
        filter.key === key ? { ...filter, operator: toOperator(operator) } : filter,
      ),
    );

  const handleSortKeyChange = (key: string) =>
    onSortChange({
      key: key as ProductIndexSortKeyType,
      direction: key === "title" ? "ascending" : "descending",
    });

  return (
    <IndexFilters
      onSaveView={onSaveView}
      saveAction={{
        modalTitle: "Save as new view",
        namePlaceholder: "e.g. Low stock clothing",
        validateName: (name) =>
          existingViewNames.some(
            (existing) => existing.toLowerCase() === name.toLowerCase(),
          )
            ? "A view with this name already exists"
            : undefined,
      }}
    >
      <IndexFilters.SearchField
        tabs={
          <Tabs
            tabs={tabs}
            selected={selectedTab}
            onSelect={(tabId: string | number) => onSelectTab(String(tabId))}
            compact
          />
        }
        queryValue={query}
        queryPlaceholder="Search products, vendors, tags"
        onQueryChange={onQueryChange}
        onQueryClear={() => onQueryChange("")}
        filters={filterDefinitions}
        appliedFilters={pills}
        onAddFilter={handleAddFilter}
        onFilterSelect={handleFilterSelect}
        onOperatorChange={handleOperatorChange}
        onClearAll={onClearAll}
      />

      <IndexFilters.Actions>
        {/* Delete is only relevant while a saved view is selected. */}
        <IndexFilters.ViewVisibleActiveFilter visible={Boolean(onDeleteView)}>
          <Button variant="tertiary" tone="critical" onClick={onDeleteView}>
            Delete view
          </Button>
        </IndexFilters.ViewVisibleActiveFilter>

        {/* Shown only while a search or filter is active. */}
        <IndexFilters.ViewVisibleActiveFilter>
          <Button variant="tertiary" icon="export" onClick={onExport}>
            Export
          </Button>
        </IndexFilters.ViewVisibleActiveFilter>

        <IndexFilters.ViewOptions>
          <IndexFilters.ViewOptionsSort
            options={sortOptions}
            value={sort.key}
            onChange={handleSortKeyChange}
          />
          <IndexFilters.ViewOptionsToggles
            items={[
              {
                key: "hideArchived",
                label: "Hide archived",
                icon: "archive",
                checked: hideArchived,
                onChange: onHideArchivedChange,
              },
            ]}
          />
          <IndexFilters.ViewOptionsColumns columns={columns} onChange={onColumnsChange} />
        </IndexFilters.ViewOptions>

        <Button
          variant="tertiary"
          icon="refresh"
          accessibilityLabel="Refresh products"
          loading={refreshing}
          onClick={onRefresh}
        />
      </IndexFilters.Actions>
    </IndexFilters>
  );
}

import type { ReactNode } from "react";
import { Badge, IndexTable, InlineStack, Text, Thumbnail } from "@xco-agency/corex-ui";
import type { IndexTableHeadingType } from "@xco-agency/corex-ui";
import { formatDate, formatPrice } from "../utils";
import type {
  ProductIndexColumnKeyType,
  ProductIndexItemType,
  ProductIndexSortKeyType,
  ProductIndexStatusType,
  ProductIndexTablePropsType,
} from "../types";

const STATUS_TONES: Record<ProductIndexStatusType, "success" | "info" | "neutral"> = {
  active: "success",
  draft: "info",
  archived: "neutral",
};

const STATUS_LABELS: Record<ProductIndexStatusType, string> = {
  active: "Active",
  draft: "Draft",
  archived: "Archived",
};

/** Columns that sort the table when their heading is clicked. */
const SORT_KEY_BY_COLUMN: Partial<
  Record<ProductIndexColumnKeyType, ProductIndexSortKeyType>
> = {
  product: "title",
  inventory: "inventory",
  price: "price",
  updatedAt: "updatedAt",
};

/** Cell content per column key; the columns list only sets order and visibility. */
const renderCell: Record<
  ProductIndexColumnKeyType,
  (product: ProductIndexItemType) => ReactNode
> = {
  product: (product) => (
    <InlineStack gap="small-200" alignItems="center" wrap={false}>
      <Thumbnail
        source={product.imageUrl ?? undefined}
        alt={product.title}
        size="small"
      />
      <Text heading>{product.title}</Text>
    </InlineStack>
  ),
  status: (product) => (
    <Badge tone={STATUS_TONES[product.status]}>{STATUS_LABELS[product.status]}</Badge>
  ),
  inventory: (product) => (
    <Text tone={product.inventory === 0 ? "critical" : undefined} color="subdued">
      {product.inventory === 0
        ? "Out of stock"
        : `${product.inventory} in stock for ${product.variants} variant${product.variants === 1 ? "" : "s"}`}
    </Text>
  ),
  category: (product) => <Text>{product.category}</Text>,
  vendor: (product) => <Text>{product.vendor}</Text>,
  productType: (product) => <Text>{product.productType}</Text>,
  channels: (product) => <Text>{product.channels}</Text>,
  price: (product) => <Text>{formatPrice(product.price)}</Text>,
  updatedAt: (product) => <Text color="subdued">{formatDate(product.updatedAt)}</Text>,
};

/**
 * Products IndexTable: visible columns follow the IndexFilters column settings,
 * with selection, bulk actions, sortable headings and pagination.
 */
export function ProductIndexTable({
  products,
  totalCount,
  columns,
  selectedIds,
  allSelected,
  onSelectionChange,
  sort,
  onSortChange,
  page,
  pageCount,
  pageSize,
  onPageChange,
  onBulkStatusChange,
  onBulkDelete,
  onOpenProduct,
  emptyState,
  loading,
}: ProductIndexTablePropsType) {
  const visibleColumns = columns.filter((column) => column.visible !== false);

  const headings: IndexTableHeadingType[] = visibleColumns.map((column) => {
    const sortKey = SORT_KEY_BY_COLUMN[column.key];
    return {
      id: column.key,
      title: column.label,
      minWidth: column.minWidth,
      alignment: column.alignment,
      sortable: Boolean(sortKey),
      defaultSortDirection: sortKey === "title" ? "ascending" : "descending",
    };
  });

  const sortColumnIndex = visibleColumns.findIndex(
    (column) => SORT_KEY_BY_COLUMN[column.key] === sort.key,
  );

  const handleSort = (columnIndex: number, direction: "ascending" | "descending") => {
    const key = SORT_KEY_BY_COLUMN[visibleColumns[columnIndex]!.key];
    if (key) onSortChange({ key, direction });
  };

  const start = totalCount === 0 ? 0 : (page - 1) * pageSize + 1;
  const end = Math.min(page * pageSize, totalCount);

  return (
    <IndexTable
      resourceName={{ singular: "product", plural: "products" }}
      itemCount={totalCount}
      selectedItemsCount={allSelected ? "All" : selectedIds.length}
      onSelectionChange={onSelectionChange}
      headings={headings}
      sortColumnIndex={sortColumnIndex >= 0 ? sortColumnIndex : undefined}
      sortDirection={sort.direction}
      onSort={handleSort}
      loading={loading}
      emptyState={emptyState}
      promotedBulkActions={[
        { content: "Set as active", onAction: () => onBulkStatusChange("active") },
        { content: "Set as draft", onAction: () => onBulkStatusChange("draft") },
      ]}
      bulkActions={[
        { content: "Archive products", onAction: () => onBulkStatusChange("archived") },
        { content: "Delete products", destructive: true, onAction: onBulkDelete },
      ]}
      pagination={{
        hasPrevious: page > 1,
        hasNext: page < pageCount,
        label: `${start}–${end} of ${totalCount}`,
        onPrevious: () => onPageChange(page - 1),
        onNext: () => onPageChange(page + 1),
      }}
    >
      {products.map((product) => (
        <IndexTable.Row
          key={product.id}
          id={product.id}
          selected={selectedIds.includes(product.id)}
          onClick={() => onOpenProduct(product)}
        >
          {visibleColumns.map((column) => (
            <IndexTable.Cell
              key={column.key}
              alignment={column.alignment}
              {...(column.sticky ? { sticky: column.sticky } : {})}
            >
              {renderCell[column.key](product)}
            </IndexTable.Cell>
          ))}
        </IndexTable.Row>
      ))}
    </IndexTable>
  );
}

import type { ReactNode } from "react";
import type {
  IndexFilterColumnItemType,
  IndexFilterItemType,
  IndexFilterSortOptionType,
  IndexFiltersSavedViewType,
  IndexTableSortDirectionType,
  TabItemType,
} from "@xco-agency/corex-ui";

export type ProductIndexStatusType = "active" | "draft" | "archived";

export type ProductIndexItemType = {
  id: string;
  title: string;
  imageUrl: string;
  status: ProductIndexStatusType;
  inventory: number;
  variants: number;
  category: string;
  vendor: string;
  productType: string;
  tags: string[];
  channels: number;
  price: number;
  updatedAt: string;
};

/** Built-in status tabs; saved views add their own ids next to these. */
export type ProductIndexStatusTabIdType = "all" | ProductIndexStatusType;

export type ProductIndexFilterKeyType = "status" | "vendor" | "category" | "tag";

export type ProductIndexOperatorType = "is" | "is_not";

/**
 * An applied filter kept in state. `onRemove` callbacks are attached when the
 * filters are handed to `IndexFilters`, so state stays plain and serializable.
 */
export type ProductIndexFilterValueType = {
  key: ProductIndexFilterKeyType;
  operator: ProductIndexOperatorType;
  value: string | string[];
};

export type ProductIndexSortKeyType = "title" | "inventory" | "price" | "updatedAt";

export type ProductIndexSortType = {
  key: ProductIndexSortKeyType;
  direction: IndexTableSortDirectionType;
};

/** A view saved with the built-in IndexFilters save action, rendered as a tab. */
export type ProductIndexSavedViewType = {
  id: string;
  name: string;
  query: string;
  filters: ProductIndexFilterValueType[];
};

export type ProductIndexColumnKeyType =
  | "product"
  | "status"
  | "inventory"
  | "category"
  | "vendor"
  | "productType"
  | "channels"
  | "price"
  | "updatedAt";

export type ProductIndexColumnType = IndexFilterColumnItemType & {
  key: ProductIndexColumnKeyType;
  /** Narrowest the table column may get, in px. */
  minWidth?: number;
  alignment?: "start" | "center" | "end";
  sticky?: "left" | "right";
};

export type ProductIndexFiltersPropsType = {
  tabs: TabItemType[];
  selectedTab: string;
  onSelectTab: (tabId: string) => void;
  query: string;
  onQueryChange: (query: string) => void;
  filterDefinitions: IndexFilterItemType[];
  appliedFilters: ProductIndexFilterValueType[];
  onAppliedFiltersChange: (filters: ProductIndexFilterValueType[]) => void;
  onClearAll: () => void;
  sortOptions: IndexFilterSortOptionType[];
  sort: ProductIndexSortType;
  onSortChange: (sort: ProductIndexSortType) => void;
  hideArchived: boolean;
  onHideArchivedChange: (hide: boolean) => void;
  columns: ProductIndexColumnType[];
  onColumnsChange: (columns: ProductIndexColumnType[]) => void;
  existingViewNames: string[];
  onSaveView: (view: IndexFiltersSavedViewType) => void;
  /** Set when the selected tab is a saved view; shows the delete action. */
  onDeleteView?: () => void;
  onExport: () => void;
  onRefresh: () => void;
  refreshing: boolean;
};

export type ProductIndexTablePropsType = {
  products: ProductIndexItemType[];
  totalCount: number;
  columns: ProductIndexColumnType[];
  selectedIds: string[];
